def source(text):
    """Translate an Arabic template/script source into English, segment by segment (unknown segments stay)."""
    def rep(m):
        raw = m.group(0); t = raw.rstrip(' (-–/+*:·'); tail = raw[len(t):]; core = t.strip(); lead = t[:len(t) - len(t.lstrip())]
        en = C.get(core)
        if en is not None: return lead + en + tail
        # a known phrase joined to others («المعتمِد: حفظ البيانات», «حفظ مسودة تصحيح (3 تعديل)»): translate each part
        parts = re.split(r'(\s*[:،—]\s*|\s*\(\s*|\s*\)\s*)', core)
        if len(parts) > 1 and any(p.strip() in C for p in parts):
            return lead + ''.join(C.get(p.strip(), p) if p.strip() else p for p in parts) + tail
        return raw
    return SEG.sub(rep, text)


def qlabel_en(s):
    m = re.match(r'^الربع (الأول|الثاني|الثالث|الرابع) (\d{4})م?$', s.strip())
    return f'{QORD[m.group(1)]} {m.group(2)}' if m else None


def date_en(s):
    def rep(m): return f'{int(m.group(1))} {EN_M[AR_M.index(m.group(2))]} {m.group(3)}'
    return re.sub(rf'(\d{{1,2}}) ({"|".join(AR_M)}) (\d{{4}})م?', rep, s)


def _n(x):
    return T(x, 'en')


_VAL = [   # validation messages built from field names
    (re.compile(r'^(.+?): سلّم البيان إلى «(.+?)»(?: — (.*))?$', re.S), lambda m: f'{m.group(1)}: handed the statement to “{_n(m.group(2))}”' + (f' — {m.group(3)}' if m.group(3) else '')),
    (re.compile(r'^(.+?): أعاد البيان إلى «(.+?)» — (.*)$', re.S), lambda m: f'{m.group(1)}: returned the statement to “{_n(m.group(2))}” — {m.group(3)}'),
    (re.compile(r'^(.+?): سجّل مراجعة «(.+?)»(?: — (.*))?$', re.S), lambda m: f'{m.group(1)}: recorded the {_n(m.group(2))} review' + (f' — {m.group(3)}' if m.group(3) else '')),
    (re.compile(r'^الحقل «(.+)» فارغ\.$'), lambda m: f'“{_n(m.group(1))}” is empty.'),
    (re.compile(r'^أكبر الاستثمارات: (\d+) بندًا بدل 10\.$'), lambda m: f'Top ten investments: {m.group(1)} items instead of 10.'),
    (re.compile(r'^«(.+)»: المجموع ([\d.]+)% لا 100%\.$'), lambda m: f'“{_n(m.group(1))}”: total {m.group(2)}%, not 100%.'),
    (re.compile(r'^«(.+)»: بند بلا اسم في إحدى اللغتين\.$'), lambda m: f'“{_n(m.group(1))}”: an item has no name in one of the languages.'),
    (re.compile(r'^في الربع الأول يجب أن يساوي عائد «منذ بداية السنة» عائد الأشهر الثلاثة \((.+)\)\.$'), lambda m: f'In the first quarter the year-to-date return must equal the three-month return ({_n(m.group(1))}).'),
    (re.compile(r'^«(.+)» تغيّر أكثر من 10% عن الربع السابق\.$'), lambda m: f'“{_n(m.group(1))}” changed by more than 10% from last quarter.'),
    (re.compile(r'^بيتا (\S+) خارج النطاق المعقول لصندوق دخل\.$'), lambda m: f'Beta {m.group(1)} is outside the reasonable range for an income fund.'),
    (re.compile(r'^«(.+)» و«(.+)» متطابقان في كل الفترات\.$'), lambda m: f'“{_n(m.group(1))}” and “{_n(m.group(2))}” are identical in every period.'),
]


def T(s, lang='ar'):
    """A run-time interface string in the viewer's language."""
    if lang != 'en' or not isinstance(s, str) or not re.search(f'[{AR}]', s): return s
    if s in C: return C[s]
    for rx, fn in _VAL:
        m = rx.match(s)
        if m: return fn(m)
    q = qlabel_en(s)
    if q: return q
    s = date_en(s)
    s = re.sub(r'(\d+) (تعديل|تغيير)', r'\1 change(s)', s)
    s = re.sub(r'الربع (الأول|الثاني|الثالث|الرابع) (\d{4})م?', lambda m: f'{QORD[m.group(1)]} {m.group(2)}', s)
    return source(s)


def deep(v, lang, skip=('data', 'conflicts', 'corrections', 'verified', 's', 'items', 'details', 'ua')):
    """Translate interface strings inside a render context. Statement content is left alone."""
    if lang != 'en': return v
    if isinstance(v, str): return T(v, lang)
    if isinstance(v, list): return [deep(x, lang) for x in v]
    if isinstance(v, dict): return {k: (x if k in skip or k.endswith('_json') else deep(x, lang)) for k, x in v.items()}
    return v
